INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل صيانة خطوط الري بالتنقيط زراعة البازلاء: زيادة العمر الإنتاجي والكفاءة' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعلم كيفية العناية بخطوط الري بالتنقيط أثناء زراعة البازلاء لزيادة العمر الإنتاجي ونسبة النجاح والجدوى الزراعية. دليل شامل للفلاحين العراقيين حول الصيانة الدورية وإطالة العمر الافتراضي للأنظمة الحديثة لضمان ري فعال واقتصادي.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
